UPDATE `fza_usuarios_perfiles` SET `VALUE_TEXT_USUPER` = 'SELECT *\r\nfrom VI_FACTURAS_PRINT\r\nwhere SERIE_FAC = \'ANA/2023\' \r\nAND NUMERO_FAC = \'000003\'\r\norder by NUMERO_FAC Asc\r\n' WHERE `USUARIO_GRUPO_USUPER` = 'Administrador' AND `KEY_USUPER` = 'dmFacturas' AND `SUBKEY_USUPER` = 'unqryFacPrint' AND `VALUE_TEXT_USUPER` = 'SELECT *\r\nfrom vi_facturas_print\r\nwhere SERIE_FAC = \'ANA/2023\' \r\nAND NUMERO_FAC = \'000003\'\r\norder by NUMERO_FAC Asc\r\n';
UPDATE `fza_usuarios_perfiles` SET `VALUE_TEXT_USUPER` = 'SELECT * \r\nFROM VI_IVAS\r\n\r\n' WHERE `USUARIO_GRUPO_USUPER` = 'Administrador' AND `KEY_USUPER` = 'dmFacturas' AND `SUBKEY_USUPER` = 'unqryIvas' AND `VALUE_TEXT_USUPER` = 'SELECT * \r\nFROM vi_ivas\r\n\r\n';
UPDATE `fza_usuarios_perfiles` SET `VALUE_TEXT_USUPER` = 'SELECT * \r\nFROM FZA_IVAS_TIPOS\r\n\r\n' WHERE `USUARIO_GRUPO_USUPER` = 'Administrador' AND `KEY_USUPER` = 'dmFacturas' AND `SUBKEY_USUPER` = 'unqryIvasTipos' AND `VALUE_TEXT_USUPER` = 'SELECT * \r\nFROM fza_ivas_tipos\r\n\r\n';
UPDATE `fza_usuarios_perfiles` SET `VALUE_TEXT_USUPER` = 'SELECT *\r\nFROM vi_FACTURAS_LINEAS\r\nwhere NUMERO_FAC_FACLIN = :NUMERO_FAC\r\nAND SERIE_FAC_FACLIN = :SERIE_FAC\r\norder by NUMERO_FAC_FACLIN, SERIE_FAC_FACLIN, LINEA_FACLIN ASC\r\n' WHERE `USUARIO_GRUPO_USUPER` = 'Administrador' AND `KEY_USUPER` = 'dmFacturas' AND `SUBKEY_USUPER` = 'unqryLinFac' AND `VALUE_TEXT_USUPER` = 'SELECT *\r\nFROM vi_facturas_lineas\r\nwhere NUMERO_FAC_FACLIN = :NUMERO_FAC\r\nAND SERIE_FAC_FACLIN = :SERIE_FAC\r\norder by NUMERO_FAC_FACLIN, SERIE_FAC_FACLIN, LINEA_FACLIN ASC\r\n';
UPDATE `fza_usuarios_perfiles` SET `VALUE_TEXT_USUPER` = 'SELECT *\r\n FROM vi_FACTURAS_LINEAS_print\r\nWHERE NUMERO_FAC_FACLIN = :NUMERO_FAC\r\n  AND SERIE_FAC_FACLIN = :SERIE_FAC\r\nORDER BY LINEA_FACLIN;\r\n' WHERE `USUARIO_GRUPO_USUPER` = 'Administrador' AND `KEY_USUPER` = 'dmFacturas' AND `SUBKEY_USUPER` = 'unqryLinFacPrint' AND `VALUE_TEXT_USUPER` = 'SELECT *\r\n FROM vi_facturas_lineas_print\r\nWHERE NUMERO_FAC_FACLIN = :NUMERO_FAC\r\n  AND SERIE_FAC_FACLIN = :SERIE_FAC\r\nORDER BY LINEA_FACLIN;\r\n';
UPDATE `fza_usuarios_perfiles` SET `VALUE_TEXT_USUPER` = 'SELECT DISTINCT SERIE_CON, DEFAULT_CON\r\nFROM fza_CONTADORES\r\nWHERE TIPO_DOC_CON=\'FC\' AND ESACTIVO_CON = \'S\'\r\nORDER BY DEFAULT_CON DESC\r\n' WHERE `USUARIO_GRUPO_USUPER` = 'Administrador' AND `KEY_USUPER` = 'dmFacturas' AND `SUBKEY_USUPER` = 'unqrySeries' AND `VALUE_TEXT_USUPER` = 'SELECT DISTINCT SERIE_CON, DEFAULT_CON\r\nFROM fza_contadores\r\nWHERE TIPO_DOC_CON=\'FC\' AND ESACTIVO_CON = \'S\'\r\nORDER BY DEFAULT_CON DESC\r\n';
